config:
events {}

http {

    include /etc/nginx/mime.types;

    default_type application/octet-stream;

    sendfile on;

    map $http_upgrade $connection_upgrade {

        default upgrade;

        "" close;

    }

    server {
        listen 80 default_server;
        listen [::]:80 default_server;
        server_name _;
        location ^~ /.well-known/acme-challenge/ {
            proxy_pass http://127.0.0.1:3000/api/acme-challenge/;
            proxy_set_header Host $host;
            proxy_set_header X-Forwarded-Proto $scheme;
            proxy_set_header X-Real-IP $remote_addr;
        }
        location ^~ / {
            return 404;
        }
    }

    server {
        listen 80;
        listen [::]:80;
        server_name x.home.arpa;
        location ^~ /.well-known/acme-challenge/ {
            proxy_pass http://127.0.0.1:3000/api/acme-challenge/;
            proxy_set_header Host $host;
            proxy_set_header X-Forwarded-Proto $scheme;
            proxy_set_header X-Real-IP $remote_addr;
        }
        return 308 https://$host$request_uri;
    }

    server {
        listen 443 ssl http2;
        listen [::]:443 ssl http2;
        server_name x.home.arpa;
        location ^~ /.well-known/acme-challenge/ {
            proxy_pass http://127.0.0.1:3000/api/acme-challenge/;
            proxy_set_header Host $host;
            proxy_set_header X-Forwarded-Proto $scheme;
            proxy_set_header X-Real-IP $remote_addr;
        }
        ssl_certificate /etc/nginx/certs/cert-x.crt;
        ssl_certificate_key /etc/nginx/certs/cert-x.key;
        ssl_protocols TLSv1.2 TLSv1.3;
        auth_basic "ProxyCore";
        auth_basic_user_file /run/proxycore/basic-auth/secret-basic-2;
        proxy_http_version 1.1;
        proxy_connect_timeout 5s;
        proxy_send_timeout 60s;
        proxy_read_timeout 60s;
        client_header_timeout 15s;
        client_max_body_size 10m;
        proxy_set_header Host custom.example;
        location / {
            proxy_pass http://10.0.0.70:8081;
        }
    }

}

stream {

}

